 print('STORAGE',p,shutil.disk_usage(p))
 try:
  q=p+'/storage-probe';open(q,'w').write('probe');os.unlink(q);print('WRITABLE',p)
 except OSError as e:print('WRITE_FAILED',p,repr(e))
